import threading
import time
import unittest

import launch
import launch_ros.actions
import launch_testing
import launch_testing.actions
import launch_testing.markers
import pytest

import rclpy
from rclpy.node import Node
from std_msgs.msg import Int32


@pytest.mark.launch_test
def generate_test_description():
    echo_node = launch_ros.actions.Node(
        package='echo_pkg',
        executable='echo_node',
        name='echo_node',
    )

    return launch.LaunchDescription([
        echo_node,
        launch_testing.actions.ReadyToTest(),
    ]), {'echo_node': echo_node}


class TestEchoNodeLink(unittest.TestCase):

    @classmethod
    def setUpClass(cls):
        rclpy.init()

    @classmethod
    def tearDownClass(cls):
        rclpy.shutdown()

    def setUp(self):
        self.node = Node('test_echo_node_link')

    def tearDown(self):
        self.node.destroy_node()

    def test_value_published_on_out(self, proc_output):
        received_msgs = []

        sub = self.node.create_subscription(
            Int32, '/out', lambda msg: received_msgs.append(msg.data), 10)
        pub = self.node.create_publisher(Int32, '/in', 10)

        try:
            # Spin in a background thread so we can publish and wait.
            executor_thread = threading.Thread(
                target=rclpy.spin, args=(self.node,), daemon=True)
            executor_thread.start()

            # Wait for the publisher/subscription to discover the running node.
            end_time = time.time() + 10
            expected_value = 42
            published = False
            while time.time() < end_time and not received_msgs:
                if not published and pub.get_subscription_count() > 0:
                    pub.publish(Int32(data=expected_value))
                    published = True
                time.sleep(0.1)

            self.assertTrue(received_msgs, 'No message received on /out')
            self.assertEqual(received_msgs[0], expected_value)
        finally:
            rclpy.shutdown() if False else None
            self.node.destroy_subscription(sub)
            self.node.destroy_publisher(pub)
            executor = rclpy.get_default_context()
            # Trigger spin() to exit by destroying the node's context usage.
            rclpy.try_shutdown() if False else None


@launch_testing.post_shutdown_test()
class TestEchoNodeShutdown(unittest.TestCase):

    def test_exit_code(self, proc_info, echo_node):
        launch_testing.asserts.assertExitCodes(proc_info, process=echo_node)

